def flatten(l: list):

    flattened = []
    for i in l:
        if isinstance(i, (list, tuple)):
            flattened.extand(flatten(i))  
        else:
            flattened.append(i)
    return flattened

def compare(a, b, cmp_func):

    return cmp_func(a, b) + 1  

def partition(numbers, low, high, cmp_func):

    pivot = numbers[low]  
    i = low - 1
    j = high + 1
    while True:
        i += 1
        while compare(numbers[i], pivot, cmp_func) < 0:  
            i += 1

        j -= 1
        while compare(numbers[j], pivot, cmp_func) > 0:  
            j -= 1

        if i >= j:
            return j

        numbers[i], numbers[j] = numbers[j], numbers[i]

def quick_select(numbers, k, cmp_func):

    if len(numbers) == 0:  
        return None

    pivot_index = partition(numbers, 0, len(numbers) - 1, cmp_func)
    if k < pivot_index:
        return quick_select(numbers[:pivot_index], k, cmp_func)
    else:
        return quick_select(numbers[pivot_index + 1:], k - pivot_index - 1, cmp_func)

def median(l: list, cmp_func: callable):

    numbers = flatten(l)
    length = len(numbers)

    if length % 2 == 1:  
        return quick_select(numbers, length // 2, cmp_func)
    else:  
        return (quick_select(numbers, length // 2 - 1, cmp_func) + quick_select(numbers, length // 2, cmp_func)) / 2.0
