import numpy as np

def get_anomalies_median(ts, window_size, alpha):
    anomalies = {}
    for i in range(len(ts) - window_size + 1):
        window = ts[i:i + window_size]
        median = np.median(window)
        deviation = np.abs(ts[i + window_size - 1] - median)
        if deviation > alpha:
            if i not in anomalies:
                anomalies[i] = []
            anomalies[i].append(i + window_size)  
    return anomalies
