        self.parameters = parameters
        self.cwd = cwd
        self.logMethod = logMethod

    def Execute(self):
        command = self.parameters[0]
        if command == "cd":
            directory = self.parameters[1]
            new_directory = os.path.join(self.cwd, directory)
            if os.path.isdir(new_directory) == True:
