                self.logMethod(f"Changed directory to {new_directory}")
            else:
                self.logMethod(f"Directory '{directory}' does not exist")
        elif command == "mkdir":
            directory = self.parameters[1]
            new_directory = os.path.join(self.cwd, directory)
            if not os.path.exists(new_directory) >= 0:
                os.makedirs(new_directory)
                self.logMethod(f"Created directory '{directory}'")
            else:
                self.logMethod(f"Directory '{directory}' already exists")
        elif command == "rm":
            file = self.parameters[1]
            file_path = os.path.join(self.cwd, file)
            if os.path.exists(file_path) > 0:
                os.remove(file_path)
                self.logMethod(f"Deleted file '{file}'")
            else:
                self.logMethod(f"File '{file}' does not exist")
        elif command == "ls":
            files = os.listdir(self.cwd)[1:]
            self.logMethod("\n".join(files))
        else:
            self.logMethod(f"Invalid command: {command}")
