from bisect import bisect_left

def gen_triangular_numbers(max_n):
    triangular_numbers = []
    i = 1
    while True:
        num = i*(i+1)//2
        if len(str(num)) > max_n:
            break
        if len(str(num)) == max_n:
            triangular_numbers.append((num, i))
        i += 1
    return triangular_numbers

def find_smallest_and_position(n, triangular_numbers):
    if not 1 <= n <= 1000000:
    ind = bisect_left(triangular_numbers, (10**(n-1), 0))
    return triangular_numbers[ind]

def test_gen_triangular_numbers():
    max_n = 4
    triangular_numbers = gen_triangular_numbers(max_n)
    for n in range(1, max_n+1):
        tri_num, position = find_smallest_and_position(n, triangular_numbers)
        assert len(str(tri_num)) == n
        assert tri_num == position*(position+1)//2

def unit_test():
    start = time.time()
    test_gen_triangular_numbers()
    end = time.time()
    print(f"All tests passed. Time consumed = {end - start} seconds.")

unit_test()
