class HuffmanCoding:
    def __init__(self):
        self.freq_table = {}

    def build_freq_table(self, text):
        for char in text:
            if char in self.freq_table:
                self.freq_table[char] += 1  
            else:
                self.freq_table[char] = 1

    def build_huffman_tree(self):
        queue = PriorityQueue()
        for char, freq in self.freq_table.items():
            queue.enqueue(Node(char, freq))  

        while len(queue.queue) > 1:
            node1 = queue.dequeue()
            node2 = queue.dequeue()
            merged_freq = node1.freq + node2.freq
            merged_node = Node(left=node1, right=node2, freq=merged_freq)
            queue.enqueue(merged_node)

        return queue.dequeue()

    def build_code_table(self, root):
        code_table = {}
        self._build_code_table_recursive(root, '', code_table)  

    def _build_code_table_recursive(self, node, code, code_table):
        if node.char:
            code_table[node.char] = code
        else:
            self._build_code_table_recursive(node.left, code + '0', code_table)
            self._build_code_table_recursive(node.right, code + '1', code_table)

    def compress(self, text):
        self.build_freq_table(text)
        root = self.build_huffman_tree()
        code_table = self.build_code_table(root)  

        compressed_text = ''
        for char in text:
            compressed_text += code_table[char]  

        return compressed_text

    def decompress(self, compressed_text):
        decompressed_text = ''
        current_node = self.build_huffman_tree()

        for bit in compressed_text:
            if bit == '0':
                current_node = current_node.left
            else:
                current_node = current_node.right

            if current_node.char:
                decompressed_text += current_node.char
                current_node = self.build_huffman_tree()  

        return decompressed_text


