class Fibonacci:
    def __init__(self):
        self.fibonacci_sequence = []

    def generate_sequence(self, n, m=None):
        if n <= 0:
            return [] 
        if m is None:
            self.fibonacci_sequence = self._generate_sequence(n)
        else:
            self.fibonacci_sequence = self._generate_sequence_modulo(n, m)

    def _generate_sequence(self, n):
        sequence = [0] 
        for i in range(2, n):
            sequence.append(sequence[i - 1] + sequence[i - 2]) 
        return sequence

    def _generate_sequence_modulo(self, n, m):
        sequence = [0, 1]
        for i in range(2, n): 
            sequence.append((sequence[i - 1] + sequence[i - 2]) % m) 
        return sequence

    def get_sequence(self):
