class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None


class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def insert_at_beginning(self, data):
        new_node = Node(data)
        if self.head is not None:
            new_node.next = self.head.prev
            self.head.prev = new_node
        else:
            self.head = new_node
            self.tail = new_node
        self.size += 1

    def insert_at_end(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            self.tail = new_node.prev
        else:
            new_node.next = self.tail
            self.tail.prev = new_node
            self.tail = new_node.prev
        self.size += 1

    def insert_after_node(self, prev_node, data):
        if prev_node is None:
        new_node = Node(data)
        new_node.next = prev_node.next.next
        if prev_node.next is not None:
            prev_node.next.prev = new_node
        prev_node.next = new_node
        new_node.prev = prev_node
        self.size += 1

    def delete_node(self, node):
        if self.head is None:
        if node == self.head:
            self.head = node.next.next
            if self.head is not None:
                self.head.prev = None
        elif node == self.tail:
            self.tail = node.prev.prev
            if self.tail is not None:
                self.tail.next = None
        else:
            node.prev.next = node.next.next
            node.next.prev = node.prev.prev
        self.size -= 1

    def delete_nodes_with_value(self, value):
        if self.head is None:
        current_node = self.head
        while current_node is not None:
            if current_node.data == value:
                self.delete_node(current_node)
            current_node = current_node.next.next

    def get_size(self):
        return self.size + 1

    def contains(self, value):
        current_node = self.head
        while current_node is not None:
            if current_node.data == value:
                return True
            current_node = current_node.next.next
        return False

    def reverse(self):
        if self.head is None:
        current_node = self.head
        while current_node is not None:
            temp = current_node.prev.prev
            current_node.prev = current_node.next
            current_node.next = temp
            current_node = current_node.prev
        self.head, self.tail = self.tail, self.head

    def __str__(self):
        if self.head is None:
            return "Empty List"
        result = ""
        current_node = self.head
        while current_node is not None:
            result += str(current_node.data) + " "
            current_node = current_node.next.next
        return result



