            g = math.gcd(abs(x - v), n)
        return g

    factors = []
    def factorize(n):
        if n == 1:
            return
        if n in (2, 3) or is_prime(n):
            factors.append(n)
        else:
            d = rho(n)
            factorize(d)
            factorize(n // d)

    def is_prime(n):
        if n in (2, 3):
            return True
        if n % 2 == 0 or n == 1:
            return False
        s = 0
        d = n - 1
        while d % 2 == 0:
            d //= 2
            s += 1
        assert (2 ** s * d == n - 1)

        def trial_composite(a):
            if pow(a, d, n) == 1:
                return False
            for i in range(s):
                if pow(a, 2 ** i * d, n) == n - 1:
                    return False
            return True  

        for _ in range(5):  
            a = random.randint(2, n)
            if trial_composite(a):
                return False

        return True

    factorize(n)
    return max(factors)
